export const json=(body,status=200,headers={})=>new Response(JSON.stringify(body),{status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store',...headers}});
export function cors(env,request){const origin=request.headers.get('Origin')||'',allowed=String(env.ALLOWED_ORIGINS||'').split(',').map(x=>x.trim());return allowed.includes(origin)?{'Access-Control-Allow-Origin':origin,'Access-Control-Allow-Headers':'Content-Type','Access-Control-Allow-Methods':'GET,POST,OPTIONS','Vary':'Origin'}:{}}
export function allowedOrigin(env,request){const origin=request.headers.get('Origin');return !origin||String(env.ALLOWED_ORIGINS||'').split(',').map(x=>x.trim()).includes(origin)}
export function page(title,body){return new Response(`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${title}</title><style>body{font:16px system-ui;background:#04131f;color:#eef8ff;max-width:720px;margin:60px auto;padding:24px}main{background:#08243a;border:1px solid #174b6b;border-radius:16px;padding:28px}blockquote{border-left:4px solid #ffc857;margin:24px 0;padding:8px 18px;white-space:pre-wrap}form{display:flex;gap:12px;flex-wrap:wrap}button{border:0;border-radius:9px;padding:12px 16px;font-weight:700;cursor:pointer}.danger{background:#b42318;color:white}</style><main><h1>${title}</h1>${body}</main></html>`,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Frame-Options':'DENY'}})}
